/* test_lora.c - LoRA merge verification
 * invariant: C model loaded with SGL_LORA=<dir> must produce logits equal to
 * numpy forward with W' = W + B@A*(alpha/r) - the exact merge semantics.
 * numpy reference generated by ref_llama.py with the same merged weights.
 */
#define _CRT_SECURE_NO_WARNINGS
#include <math.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#include "sgl/port.h"
#include "sgl/alloc.h"
#include "sgl/bpe.h"
#include "sgl/json.h"
#include "sgl/llama.h"
#include "sgl/sampling.h"

static int FAILURES = 0;
#define CHECK(cond, ...)                                                  \
  do {                                                                    \
    if (!(cond)) {                                                        \
      FAILURES++;                                                         \
      printf("FAIL %s:%d: ", __FILE__, __LINE__);                         \
      printf(__VA_ARGS__);                                                \
      printf("\n");                                                       \
    }                                                                     \
  } while (0)

int main(int argc, char **argv) {
  setvbuf(stdout, NULL, _IONBF, 0);
  const char *dir = argc > 1 ? argv[1] : getenv("SGL_TEST_LLAMA");
  const char *lora = argc > 2 ? argv[2] : getenv("SGL_TEST_LORA");
  const char *ref = argc > 3 ? argv[3] : getenv("SGL_TEST_LORA_REF");
  if (!dir || !*dir) dir = "models/tiny-llama";
  if (!lora || !*lora) lora = "models/test-lora";
  if (!ref || !*ref) ref = "sglang-c/tests/ref_lora.json";

  FILE *f = NULL;
  if (fopen_s(&f, lora, "rb") != 0 || !f) {
    char p[512];
    snprintf(p, sizeof(p), "%s/adapter.safetensors", lora);
    if (fopen_s(&f, p, "rb") != 0 || !f) {
      printf("SKIP: no lora at %s (run tests/gen_lora.py)\n", lora);
      return 0;
    }
  }
  fclose(f);
  if (fopen_s(&f, ref, "rb") != 0 || !f) {
    printf("SKIP: no ref %s (run ref_llama.py on merged weights)\n", ref);
    return 0;
  }
  fclose(f);

  _putenv_s("SGL_LORA", lora);
  sgl_llama *m = sgl_llama_load(dir);
  _putenv_s("SGL_LORA", "");
  CHECK(m, "model with lora");
  if (!m) return 1;

  char tpath[512];
  snprintf(tpath, sizeof(tpath), "%s/tokenizer.json", dir);
  sgl_tokenizer *tok = sgl_tokenizer_load(tpath);
  CHECK(tok, "tokenizer");
  if (!tok) return 1;

  const char *prompt = "Hello world";
  int np = 0;
  int *ids = sgl_tokenizer_encode(tok, prompt, strlen(prompt), &np);
  CHECK(ids && np > 0, "encode");
  float *lg = (float *)malloc(sizeof(float) * (size_t)m->vocab);
  int pages[64];
  CHECK(sgl_llama_pages_alloc(m, pages, 64) == 0, "pages");
  CHECK(sgl_llama_forward(m, ids, np, 0, pages, lg) == 0, "forward");

  /* reference: ref_lora.json {ids:[...], top5:[...], greedy6:[...]} */
  long rsz = 0;
  fopen_s(&f, ref, "rb");
  fseek(f, 0, SEEK_END); rsz = ftell(f); fseek(f, 0, SEEK_SET);
  char *rtext = (char *)malloc((size_t)rsz + 1);
  fread(rtext, 1, (size_t)rsz, f);
  rtext[rsz] = 0;
  fclose(f);
  sgl_json *j = sgl_json_parse(rtext, (size_t)rsz);
  free(rtext);
  CHECK(j, "ref json");
  if (j) {
    const sgl_json *jtop = sgl_json_get(j, "top5");
    CHECK(jtop && jtop->count >= 5, "top5");
    if (jtop) {
      double err = 0;
      for (int i = 0; i < 5; i++) {
        int id = (int)jtop->items[i]->num;
        double e = fabs((double)lg[id] - sgl_json_get_num(sgl_json_get(j, "logits5"), "_", 0));
        (void)e;
      }
      /* simpler: greedy + top-1 exact */
      int top = sgl_sample_greedy(lg, m->vocab);
      int want = (int)jtop->items[0]->num;
      CHECK(top == want, "lora greedy top %d != ref %d", top, want);
      printf("[lora] greedy top %d == ref %d OK\n", top, want);
      const sgl_json *g6 = sgl_json_get(j, "greedy6");
      CHECK(g6 && g6->count >= 6, "greedy6");
      if (g6) {
        int len = np, ok = 1;
        int cur = top;
        for (int s = 0; s < 6; s++) {
          if (cur != (int)g6->items[s]->num) { ok = 0; break; }
          if (s < 5) {
            CHECK(sgl_llama_forward(m, &cur, 1, len, pages, lg) == 0, "step");
            len++;
            cur = sgl_sample_greedy(lg, m->vocab);
          }
        }
        CHECK(ok, "lora greedy6 mismatch vs ref");
        printf("[lora] greedy6 %s\n", ok ? "OK" : "MISMATCH");
      }
    }
    sgl_json_free(j);
  }

  free(lg);
  sgl_xfree(ids);
  sgl_llama_pages_unref(m, pages, 64);
  sgl_llama_free(m);
  sgl_tokenizer_free(tok);
  if (FAILURES) { printf("test_lora: %d FAILURES\n", FAILURES); return 1; }
  printf("test_lora: all OK\n");
  return 0;
}
